#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (M, N, etc.)
#include "trmm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and B with the same semantics as the original C init_array().
 *
 * C version:
 *
 *   *alpha = 1.5;
 *   for (i = 0; i < m; i++) {
 *     for (j = 0; j < i; j++) {
 *       A[i][j] = (DATA_TYPE)((i+j) % m)/m;
 *     }
 *     A[i][i] = 1.0;
 *     for (j = 0; j < n; j++) {
 *       B[i][j] = (DATA_TYPE)((n+(i-j)) % n)/n;
 *     }
 *   }
 *
 * Halide buffer layout and indexing:
 *
 *   - A is M×M, conceptually A[row=i][col=j] in C.
 *     Here we store it as Buffer A(width = m, height = m) and access it
 *     as A(row, col) == A[i][j]. Since the first dimension is the row
 *     index, A is effectively *column-major*: for a fixed column j,
 *     A(0..m-1, j) are contiguous in memory. This makes accesses of the
 *     form A[k][i] (fixed i, varying k) unit-stride in memory.
 *
 *   - B is M×N, conceptually B[row=i][col=j] in C.
 *     We store it as Buffer B(width = n, height = m) and access it as
 *     B(col, row) == B[j][i] == B[i][j] in C. This is a standard
 *     row-major layout: for fixed row i, B(0..n-1, i) are contiguous.
 *
 * This choice (A column-major, B row-major) matches the math in the
 * TRMM kernel and gives good cache and SIMD behavior:
 *   - A[k][i] is contiguous in k,
 *   - B[k][j] is contiguous in j.
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);

    Var row("row"), col("col");
    Func init_A("init_A"), init_B("init_B");

    // Make Expr versions of m and n for use inside Halide expressions.
    Expr m_expr = m;
    Expr n_expr = n;

    // A(row, col) == A[i][j] in the original C.
    //
    // For j < i:  A[i][j] = ((i + j) % m) / m
    // For j == i: A[i][i] = 1.0
    // For j > i:  A[i][j] = 0.0 (never used by the kernel, but defined anyway)
    init_A(row, col) =
        select(col < row,
               cast<num_t>(((row + col) % m_expr)) / cast<num_t>(m_expr),
               select(col == row,
                      static_cast<num_t>(1.0),
                      static_cast<num_t>(0.0)));

    // B(col, row) == B[i][j] in the original C:
    //   B[i][j] = ( (n + (i - j)) % n ) / n
    init_B(col, row) =
        cast<num_t>(((n_expr + (row - col)) % n_expr)) / cast<num_t>(n_expr);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;

    // Buffer layout:
    //   A: M x M  -> Buffer(m, m), accessed as A(row, col) == A[i][j]
    //   B: M x N  -> Buffer(n, m), accessed as B(col, row) == B[j][i] == B[i][j]
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    // A is column-major: A_param(k, i) == A[k][i] (row k, col i)
    // B is row-major (transposed in Buffer): B_param(j, i) == B[i][j]
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars
    Var i("i"), j("j");

    // Reduction domain over k in [0, m)
    RDom k(0, m, "k");

    // Func representing the result B := alpha * A^T * B_in
    //
    // Original C kernel (0-based indices):
    //
    //   for (i = 0; i < M; i++)
    //     for (j = 0; j < N; j++) {
    //       for (k = i+1; k < M; k++)
    //         B[i][j] += A[k][i] * B[k][j];
    //       B[i][j] = alpha * B[i][j];
    //     }
    //
    // All reads of B[k][j] use the original B values (no in-place
    // dependence across rows), so the final value can be expressed as:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(k, i)         (column-major A)
    //   B[k][j]  -> B_param(j, k)         (row-major B_in)
    //   B[i][j]  -> B_param(j, i)
    //
    // We implement "k from i+1..M-1" via a select inside a reduction
    // over k in [0..M-1]. This avoids making the RDom bounds depend
    // on i, which keeps scheduling simple while still skipping work
    // for k <= i at runtime.
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(0);

    trmm(j, i) = alpha_expr *
                 (B_param(j, i) +
                  sum(select(k > i,
                             A_param(k, i) * B_param(j, k),
                             zero)));

    // ------------------------------------------------------------
    // Schedule: cache- and SIMD-friendly TRMM
    // ------------------------------------------------------------
    //
    //   - j (columns of B) is the unit-stride dimension in memory:
    //       B_param(j, i) == B[i][j] and B is row-major.
    //     So we vectorize across j.
    //
    //   - A is stored column-major (A_param(k, i) == A[k][i]), so
    //     accesses along k are contiguous in memory.
    //
    //   - We tile i and j for cache locality, split k for better
    //     control of the reduction, vectorize across j, and
    //     parallelize across tiles of i (rows).
    //

    // Choose a reasonable vector width for the host CPU.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes; tuned for a generic multi-core x64 CPU.
    const int tile_i = 32;   // rows per tile
    const int tile_j = 64;   // columns per tile
    const int tile_k = 32;   // k slice size

    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar k_outer("k_outer"), k_inner("k_inner");

    // Pure definition tiling and ordering:
    //
    //   for io (tiles of rows)
    //     for jo (tiles of cols)
    //       for ii (rows in tile)
    //         for jj (cols in tile, innermost & contiguous)
    trmm
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        .reorder(jj, ii, jo, io)
        .vectorize(jj, vec_width)
        .parallel(io); // distribute row tiles across threads

    // Reduction update schedule:
    //
    // Make the update traverse the same (io, jo, ii, jj) tiling, but
    // reorder the reduction loop so that for each (i, tile) we get:
    //
    //   for io:
    //     for jo:
    //       for ii:
    //         for k_outer:
    //           for k_inner:
    //             for jj:
    //               accumulate into trmm(jj, ii)
    //
    // This effectively yields, for each row i, a loop of the form:
    //
    //   for each k tile:
    //     for each k in that tile:
    //       for each jj in tile_j:
    //         trmm(i,jj) += A(k,i) * B(k,jj);
    //
    // which is BLAS-like: A(k,i) is reused across jj, and B(k, jj)
    // is streamed contiguously along jj.
    trmm.update()
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        .split(k, k_outer, k_inner, tile_k)
        .reorder(jj, k_inner, k_outer, ii, jo, io)
        .vectorize(jj, vec_width)
        .parallel(io); // same parallelism strategy for the update

    // Compile the kernel to machine code
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    // B_result(j, i) == B_out[i][j]
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: B_result(jj, ii) == B[ii][jj] in the original C code
                std::cerr << B_result(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
