     * *original* B (no in-place dependence across rows), so the final value
     * can be expressed in closed form as:
     *
     *   B_out[i][j] = alpha * ( B_in[i][j] +
     *                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
     *
     * Mapping indices to Halide (recall Buffer(j, i) == C-style C[i][j]):
     *   A[k][i]  -> A_param(i, k)     (column i, row k)
     *   B[k][j]  -> B_param(j, k)     (column j, row k)
     *   B[i][j]  -> B_param(j, i)
     *
     * To expose a proper Halide reduction that we can schedule, we use an
     * explicit update definition:
     *
     *   trmm(j, i) = alpha * B_in(i, j);
     *   trmm(j, i) += alpha * sum_{k} [k > i] * A(i, k) * B_in(k, j);
     *
     * where [k > i] is expressed as a select(). This is algebraically
     * equivalent to the closed form above:
     *   alpha * B + alpha * sum(...) == alpha * (B + sum(...)).
     */
    Func trmm("trmm");

    Expr alpha_expr = cast<num_t>(alpha);
    Expr zero = cast<num_t>(0);

    // Pure definition: initialize with the scaled diagonal contribution.
    trmm(j, i) = alpha_expr * B_param(j, i);

    // Reduction update: accumulate strictly lower-triangular part.
    trmm(j, i) += alpha_expr *
                  select(k > i,
                         A_param(i, k) * B_param(j, k),
                         zero);

    // ------------------------
    // Schedule (performance)
    // ------------------------
    //
    // Goals on a 32-core x64 CPU:
    //   - Good cache locality via tiling in (i, j, k).
    //   - Parallelism across tiles in the i dimension.
    //   - SIMD vectorization along j (unit-stride in B).
    //   - Reasonable ILP in the reduction via unrolling k.
    //
    // Layout recap:
    //   - For both A and B, the first dimension is the column index j,
    //     which is stride-1 (row-major layout of the original C code).
    //   - For B_param(j, i), j is contiguous in memory. We will
    //     vectorize across j.
    //
    // We use:
    //   tile_i  : tile size in the i (row) dimension
    //   tile_j  : tile size in the j (column) dimension
    //   tile_k  : tile size in the reduction dimension k
    Target target = get_jit_target_from_environment();
    const int vec_width =
        std::max(1, target.natural_vector_size(type_of<num_t>()));
    const int tile_i = 32;
    const int tile_j = 64;
    const int tile_k = 32;

    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar ko("ko"), ki("ki");

    // Pure definition schedule:
    //
    //   - Tile (j, i) into tiles of size tile_j x tile_i.
    //   - Make jj (inner j) the innermost loop for unit-stride access.
    //   - Vectorize across jj.
    //   - Parallelize across io (tiles in the i dimension).
    trmm
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        // Loops from innermost to outermost: jj, ii, jo, io
        .reorder(jj, ii, jo, io)
        .vectorize(jj, vec_width)
        .parallel(io);

    // Reduction update schedule:
    //
    // We must separately schedule the update stage. We mirror the
    // tiling of the pure definition, then further split the reduction
    // variable k into (ko, ki) so that we:
    //   - traverse k in cache-friendly chunks of tile_k,
    //   - unroll ki to increase ILP,
    //   - keep jj innermost for SIMD.
    trmm.update()
        // Same tiling in (j, i) as the pure definition
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i)
        // Split the reduction over k into chunks of size tile_k
        .split(k, ko, ki, tile_k)
        // Reorder from innermost outwards:
        //   jj  : innermost (vectorized)
        //   ki  : inner part of reduction
        //   ii  : rows within tile
        //   jo  : tile index in j
        //   ko  : tile index in k
        //   io  : tile index in i (outermost)
        .reorder(jj, ki, ii, jo, ko, io)
        .vectorize(jj, vec_width)
        .unroll(ki);

    // Compile the kernel to machine code for this target.
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
